export async function settleConnection(
  url: string,
  outbound?: unknown,
  token = 't',
  closeAfterSettle = true
): Promise<{connected: Record<string, unknown>; frames: Array<Record<string, unknown>>}> {
  return settleClient(connectClient(url, token), outbound, closeAfterSettle);
}

export async function settleClient(
  client: WebSocket,
  outbound?: unknown,
  closeAfterSettle = false
): Promise<{connected: Record<string, unknown>; frames: Array<Record<string, unknown>>}> {
  const frames: Array<Record<string, unknown>> = [];
  let connected: Record<string, unknown> = {type: 'connected'};
  await new Promise<void>(resolve => {
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Record<string, unknown>;
      if (frame.type === 'connected') {
        connected = frame;
        frames.push(frame);
        if (outbound !== undefined) client.send(JSON.stringify(outbound));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      } else if (frame.type === 'pong') {
        frames.push(frame);
        resolve();
      } else {
        frames.push(frame);
      }
    });
  });
  if (closeAfterSettle) {
    const closed = new Promise<void>(resolve => client.once('close', () => resolve()));
    client.close();
    await closed;
  }
  return {connected, frames};
}

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

